// Development reference only; never shipped as part of d2-rs.
//
// Existing-route oracle for recipe `tala-route-geometry`
// (tools/fixtures/tala-oracle.toml): reads the request lists generated by
// scripts/tala_oracle_fixtures.py on stdin and writes, per request, the
// public d2talalayout.RouteEdges error and (on success) the routed graph.
//
//   - requested_routing: a two-node graph with N routed edges and a
//     requested-edge list (repeated, foreign or oversized), optionally
//     cancelled: request preflight and its precedence over cancellation.
//   - route_geometry: two positioned objects with authored dimensions,
//     positions, D2 width/height/top/left attributes and ChildrenArray
//     order, one routed edge: object validation order and the routed boxes.
package main

import (
	"context"
	"encoding/json"
	"os"
	"strconv"

	"github.com/d2lang/d2/d2graph"
	"github.com/d2lang/d2/d2layouts/d2talalayout"
	"github.com/d2lang/d2/lib/geo"
)

type requestedInput struct {
	Name       string `json:"name"`
	GraphEdges int    `json:"graph_edges"`
	Requested  []int  `json:"requested"`
	Oversized  bool   `json:"oversized"`
	Cancel     bool   `json:"cancel"`
}

type node struct {
	ID       string            `json:"id"`
	Position []string          `json:"position"`
	Width    string            `json:"width"`
	Height   string            `json:"height"`
	Attrs    map[string]string `json:"attrs,omitempty"`
}

type geometryInput struct {
	Name       string  `json:"name"`
	Nodes      []node  `json:"nodes"`
	VisitOrder []int   `json:"visit_order"`
	Requested  []int   `json:"requested"`
	Seeds      []int64 `json:"seeds"`
	Cancel     bool    `json:"cancel"`
}

type request struct {
	RequestedRouting []requestedInput `json:"requested_routing"`
	RouteGeometry    []geometryInput  `json:"route_geometry"`
}

func number(s string) float64 {
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		panic(err)
	}
	return v
}

func object(g *d2graph.Graph, id string, box *geo.Box) *d2graph.Object {
	obj := &d2graph.Object{Graph: g, Parent: g.Root, ID: id, IDVal: id, Box: box, Children: make(map[string]*d2graph.Object)}
	g.Objects = append(g.Objects, obj)
	g.Root.Children[id] = obj
	return obj
}

func route() []*geo.Point { return []*geo.Point{geo.NewPoint(110, 50), geo.NewPoint(250, 50)} }

func run(ctx context.Context, cancel bool, g *d2graph.Graph, selected []*d2graph.Edge) (string, bool) {
	ctx, stop := context.WithCancel(ctx)
	defer stop()
	if cancel {
		stop()
	}
	if err := d2talalayout.RouteEdges(ctx, g, selected); err != nil {
		return err.Error(), false
	}
	return "", true
}

func requestedRouting(item requestedInput) map[string]any {
	g := d2graph.NewGraph()
	a := object(g, "a", geo.NewBox(geo.NewPoint(10, 20), 100, 60))
	b := object(g, "b", geo.NewBox(geo.NewPoint(250, 20), 100, 60))
	g.Root.ChildrenArray = []*d2graph.Object{a, b}
	for i := 0; i < item.GraphEdges; i++ {
		g.Edges = append(g.Edges, &d2graph.Edge{Src: a, Dst: b, Index: i, Route: route()})
	}
	// Index graph_edges names an edge that is not in the graph.
	foreign := &d2graph.Edge{Src: a, Dst: b, Index: item.GraphEdges, Route: route()}
	selected := []*d2graph.Edge{}
	if item.Oversized {
		for i := 0; i < 50001; i++ {
			selected = append(selected, g.Edges[0])
		}
	}
	for _, i := range item.Requested {
		if i < len(g.Edges) {
			selected = append(selected, g.Edges[i])
		} else {
			selected = append(selected, foreign)
		}
	}
	message, _ := run(context.Background(), item.Cancel, g, selected)
	return map[string]any{"input": item, "error": message}
}

func routeGeometry(item geometryInput) map[string]any {
	g := d2graph.NewGraph()
	for _, spec := range item.Nodes {
		box := geo.NewBox(nil, number(spec.Width), number(spec.Height))
		if spec.Position != nil {
			box.TopLeft = geo.NewPoint(number(spec.Position[0]), number(spec.Position[1]))
		}
		obj := object(g, spec.ID, box)
		for key, value := range spec.Attrs {
			scalar := &d2graph.Scalar{Value: value}
			switch key {
			case "width":
				obj.WidthAttr = scalar
			case "height":
				obj.HeightAttr = scalar
			case "top":
				obj.Top = scalar
			case "left":
				obj.Left = scalar
			default:
				panic("unknown attribute " + key)
			}
		}
	}
	for _, index := range item.VisitOrder {
		g.Root.ChildrenArray = append(g.Root.ChildrenArray, g.Objects[index])
	}
	g.Edges = append(g.Edges, &d2graph.Edge{Src: g.Objects[0], Dst: g.Objects[1], Index: 0, DstArrow: true, Route: route()})
	selected := []*d2graph.Edge{}
	for _, i := range item.Requested {
		selected = append(selected, g.Edges[i])
	}
	message, ok := run(context.Background(), item.Cancel, g, selected)
	row := map[string]any{"input": item, "error": message}
	if ok {
		row["graph"] = g
	}
	return row
}

func main() {
	var req request
	if err := json.NewDecoder(os.Stdin).Decode(&req); err != nil {
		panic(err)
	}
	out := map[string][]any{"requested_routing": {}, "route_geometry": {}}
	for _, item := range req.RequestedRouting {
		out["requested_routing"] = append(out["requested_routing"], requestedRouting(item))
	}
	for _, item := range req.RouteGeometry {
		out["route_geometry"] = append(out["route_geometry"], routeGeometry(item))
	}
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		panic(err)
	}
}
